const rows = $input.all().map(i => i.json);
const now = Date.now();
const WINDOW_MS = 72 * 60 * 60 * 1000; // 72h

const out = [];
const dated = [];

for (const r of rows) {
  const publishedRaw = (r.isoDate || r.pubDate || '').toString().trim();
  const ts = Date.parse(publishedRaw);

  if (!Number.isFinite(ts)) {
    out.push({ json: r });
    continue;
  }

  dated.push({ r, ts });

  const age = now - ts;
  if (age >= 0 && age <= WINDOW_MS) {
    out.push({ json: r });
  }
}

if (out.length === 0 && dated.length > 0) {
  dated.sort((a, b) => b.ts - a.ts);
  return dated.slice(0, 3).map(x => ({ json: x.r }));
}

return out;

const items = $input.all().map(i => i.json);

function hash(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) {
    h = ((h << 5) - h) + str.charCodeAt(i);
    h |= 0;
  }
  return Math.abs(h).toString(36);
}

const out = [];
for (const r of items) {
  const title = (r.title || '').toString().trim();
  const sourceUrl = (r.link || '').toString().trim();
  const snippet = (r.contentSnippet || r.content || '').toString().replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
  const publishedAt = (r.isoDate || r.pubDate || '').toString().trim();
  if (!title || !sourceUrl) continue;

  const base = `${sourceUrl}|${publishedAt}|${title}`;
  let externalId = `auto-${hash(base)}-${Date.now()}`;
  externalId = externalId.replace(/[^a-zA-Z0-9._:-]/g, '-').slice(0, 80);
  if (externalId.length < 3) externalId = `auto-${Date.now()}`;

  const newsText = [
    `Title: ${title}`,
    snippet ? `Summary: ${snippet}` : '',
    `Source URL: ${sourceUrl}`,
    publishedAt ? `Published: ${publishedAt}` : ''
  ].filter(Boolean).join('\n');

  out.push({
    json: {
      external_id: externalId,
      title,
      source_url: sourceUrl,
      published_at: publishedAt,
      news_text: newsText
    }
  });
}

return out;

