const TAVILY_API_KEY = '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';

const MAX_CANDIDATES = 6;
const MAX_RESULTS = 12;
const now = Date.now();

const trustedNews = new Set([
  'reuters.com','bloomberg.com','ft.com','wsj.com','theinformation.com',
  'techcrunch.com','theverge.com','openai.com','anthropic.com','nvidia.com',
  'microsoft.com','google.com'
]);

function parseTs(v = '') {
  const t = Date.parse(String(v || '').trim());
  return Number.isFinite(t) ? t : 0;
}

function domainOf(url = '') {
  try { return new URL(url).hostname.replace(/^www\./, '').toLowerCase(); }
  catch { return ''; }
}

function platformOf(domain = '') {
  if (!domain) return 'web';
  if (domain === 'x.com' || domain.endsWith('.x.com') || domain === 'twitter.com' || domain.endsWith('.twitter.com')) return 'x';
  if (domain === 'instagram.com' || domain.endsWith('.instagram.com')) return 'instagram';
  if (domain === 'reddit.com' || domain.endsWith('.reddit.com')) return 'reddit';
  if (domain === 'youtube.com' || domain.endsWith('.youtube.com') || domain === 'youtu.be') return 'youtube';
  if (domain === 'linkedin.com' || domain.endsWith('.linkedin.com')) return 'linkedin';
  if (domain === 'facebook.com' || domain.endsWith('.facebook.com')) return 'facebook';
  if (domain === 't.me' || domain.endsWith('.t.me') || domain === 'telegram.me') return 'telegram';
  return 'web';
}

function recencyBonus(publishedAt = '') {
  const t = parseTs(publishedAt);
  if (!t) return 0;
  const hours = (now - t) / 36e5;
  if (hours <= 6) return 8;
  if (hours <= 24) return 5;
  if (hours <= 48) return 3;
  if (hours <= 72) return 1;
  return 0;
}

async function searchPresenceByTitle(title) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 12000);

  try {
    const res = await fetch('https://api.tavily.com/search', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'authorization': `Bearer ${TAVILY_API_KEY}`
      },
      body: JSON.stringify({
        query: `"${title}"`,
        topic: 'news',
        search_depth: 'basic',
        max_results: MAX_RESULTS,
        include_answer: false,
        include_raw_content: false
      }),
      signal: controller.signal
    });

    if (!res.ok) {
      return { score: 0, domains: [], platforms: [], trusted_hits: 0, results_count: 0 };
    }

    const data = await res.json();
    const results = Array.isArray(data.results) ? data.results : [];

    const domains = new Set();
    const platforms = new Set();
    let trustedHits = 0;

    for (const r of results) {
      const d = domainOf(r.url || '');
      if (!d) continue;
      domains.add(d);
      platforms.add(platformOf(d));
      if (trustedNews.has(d)) trustedHits += 1;
    }

    const socialPlatforms = [...platforms].filter(p => p !== 'web');

    // امتیاز نهایی بر اساس میزان پوشش
    const score =
      (domains.size * 2) +           // سایت‌های یکتا
      (socialPlatforms.length * 5) + // پلتفرم‌های اجتماعی یکتا
      (trustedHits * 2) +            // منابع معتبر
      Math.min(results.length, 12);  // حجم نتایج

    return {
      score,
      domains: [...domains],
      platforms: [...platforms],
      trusted_hits: trustedHits,
      results_count: results.length
    };
  } finally {
    clearTimeout(timer);
  }
}

const candidates = [...rows]
  .sort((a, b) => parseTs(b.published_at || b.isoDate || b.pubDate) - parseTs(a.published_at || a.isoDate || a.pubDate))
  .slice(0, MAX_CANDIDATES);

for (const it of candidates) {
  const title = (it.title || '').toString().trim();
  if (!title) {
    it.rank_score = -999;
    continue;
  }

  let score = recencyBonus(it.published_at || it.isoDate || it.pubDate || '');

  try {
    // اگر key ست نشده بود، fallback ساده
    if (!TAVILY_API_KEY || TAVILY_API_KEY.includes('REPLACE_WITH_')) {
      const d = domainOf(it.source_url || '');
      score += trustedNews.has(d) ? 5 : 0;
      it.presence = { note: 'no tavily key' };
    } else {
      const presence = await searchPresenceByTitle(title);
      const socialCount = presence.platforms.filter(p => p !== 'web').length;
      const crossPlatformBonus = socialCount >= 2 ? 6 : 0;
      const rumorPenalty = title.toLowerCase().includes('rumor') || title.includes('شایعه') ? -8 : 0;

      score += presence.score + crossPlatformBonus + rumorPenalty;
      it.presence = presence;
    }
  } catch (e) {
    it.presence = { error: String(e) };
  }

  it.rank_score = Math.round(score * 10) / 10;
}

candidates.sort((a, b) => (b.rank_score || 0) - (a.rank_score || 0));
return [{ json: candidates[0] }];

