function normalizeTitle(raw = '') {
  return String(raw)
    .normalize('NFKC')
    .replace(/[\u200B-\u200D\uFEFF\u2060]/g, '')
    .replace(/ـ/g, '')
    .replace(/ك/g, 'ک')
    .replace(/ي/g, 'ی')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalTitle(raw = '') {
  return normalizeTitle(raw)
    .replace(/\s*[-|–—•]+\s*[^-|–—•]{1,80}$/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function canonicalUrl(raw = '') {
  try {
    const u = new URL(String(raw).trim());
    u.hash = '';
    const drop = [
      'utm_source', 'utm_medium', 'utm_campaign', 'utm_term', 'utm_content',
      'gclid', 'fbclid', 'oc', 'ved'
    ];
    for (const p of drop) u.searchParams.delete(p);
    return `${u.origin}${u.pathname}${u.search ? `?${u.searchParams.toString()}` : ''}`
      .replace(/\/$/, '')
      .toLowerCase();
  } catch {
    return '';
  }
}

const rawTitle = ($json.title ?? '').toString();
const strict = normalizeTitle(rawTitle);
const loose = canonicalTitle(rawTitle);
const source = canonicalUrl($json.source_url ?? $json.link ?? '');

if (!strict) return [{ json: $json }];

const keys = [`title:${strict}`];
if (loose && loose !== strict) keys.push(`title_loose:${loose}`);
if (source) keys.push(`url:${source}`);

for (const k of keys) {
  if (store.sentKeys[k]) return [];
}

for (const k of keys) {
  store.sentKeys[k] = now;
}

return [{ json: $json }];

