const src = $json;

const pickFirstText = (...values) => {
	for (const v of values) {
		if (typeof v === 'string' && v.trim()) return v.trim();
	}
	return '';
};

// 1) تلاش برای گرفتن متن مستقیم
let input = pickFirstText(
	src.input,
	src.text,
	src.prompt_input,
	src.description,
	src.summary,
	src.content,
	src.body
);

// 2) اگر متن مستقیم نبود، از title + خلاصه بساز
if (!input) {
	const title = pickFirstText(src.title);
	const details = pickFirstText(src.summary, src.description, src.content, src.body);

	input = [title ? `Title: ${title}` : '', details ? `Details: ${details}` : '']
		.filter(Boolean)
		.join('\n');
}

// 3) اگر هنوز خالیه، آیتم رد بشه
if (!input) return [];

// 4) پاکسازی متن
input = input
	.replace(/<[^>]*>/g, ' ')   // حذف HTML
	.replace(/\s+/g, ' ')
	.trim();

// محدودیت طول برای API
if (input.length > 2000) input = input.slice(0, 2000);

// خروجی استاندارد برای نود مدل/HTTP
return [
	{
		json: {
			input,                 // همین فیلد رو به /api/prompts بفرست
			title: src.title || null,
			source_url: src.source_url || null
		}
	}
];

const input = ($json.input ?? '').toString().trim();
if (!input) return [];
return [{ json: { input } }];

const MAX_PROMPT_LENGTH = 500;
const MAX_CAPTION_LENGTH = 1024;

return $input.all().map((item, index) => {
  const src = item.json ?? {};

  let prompt = String(src.prompt ?? "").trim();
  if (!prompt) {
    prompt = String(src.input ?? "").trim();
  }

  if (!prompt) {
    throw new Error(`Item ${index + 1}: prompt خالی است`);
  }

  if (prompt.length > MAX_PROMPT_LENGTH) {
    prompt = prompt.slice(0, MAX_PROMPT_LENGTH);
  }

  const payload = { prompt };

  const chatId = String(src.chatId ?? src.chat_id ?? "").trim();
  if (chatId) {
    payload.chatId = chatId;
  }

  const title = String(src.input ?? "")
    .replace(/^Title:\s*/i, "")
    .trim();

  if (title) {
    payload.caption = `📰 ${title}`.slice(0, MAX_CAPTION_LENGTH);
  }

  return { json: payload };
});
